</label> </div> </div> <div data-astro-cid-q3qq7mzj> <label class="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1.5 ml-1" data-astro-cid-q3qq7mzj>Tipe Jadwal / Status</label> <select id="modalType" required class="w-full h-11 px-4 rounded-xl border text-sm bg-slate-50 dark:bg-black/20 border-slate-200 dark:border-white/10 text-slate-900 dark:text-gray-100 focus:ring-2 focus:ring-accent focus:border-accent focus:outline-none transition-all font-semibold" data-astro-cid-q3qq7mzj> <option value="Kerja" data-astro-cid-q3qq7mzj>Jam Kerja (Shift)</option> <option value="Libur" data-astro-cid-q3qq7mzj>Day Off (Libur / Cuti)</option> <option value="Sakit" data-astro-cid-q3qq7mzj>Sick Leave (Sakit)</option> <option value="Izin" data-astro-cid-q3qq7mzj>Izin Keperluan Lain</option> </select> </div> <!-- Kerja-only fields (Shift Time Selection & Live Calculated Hours) --> <div id="kerjaFields" class="space-y-4" data-astro-cid-q3qq7mzj> <!-- Shift 1 (Required) --> <div class="grid grid-cols-1 sm:grid-cols-2 gap-4" data-astro-cid-q3qq7mzj> <div data-astro-cid-q3qq7mzj> <label class="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1.5 ml-1" data-astro-cid-q3qq7mzj>Mulai Shift</label> <input type="time" id="modalStartTime1" class="w-full h-11 px-4 rounded-xl border text-sm bg-slate-50 dark:bg-black/20 border-slate-200 dark:border-white/10 text-slate-900 dark:text-gray-100 focus:ring-2 focus:ring-accent focus:border-accent focus:outline-none transition-all font-semibold" data-astro-cid-q3qq7mzj> </div> <div data-astro-cid-q3qq7mzj> <label class="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1.5 ml-1" data-astro-cid-q3qq7mzj>Selesai Shift</label> <input type="time" id="modalEndTime1" class="w-full h-11 px-4 rounded-xl border text-sm bg-slate-50 dark:bg-black/20 border-slate-200 dark:border-white/10 text-slate-900 dark:text-gray-100 focus:ring-2 focus:ring-accent focus:border-accent focus:outline-none transition-all font-semibold" data-astro-cid-q3qq7mzj> </div> </div> <!-- Checkbox to enable Shift 2 --> <div class="flex items-center gap-2 px-1" data-astro-cid-q3qq7mzj> <input type="checkbox" id="enableShift2" class="rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer" data-astro-cid-q3qq7mzj> <label for="enableShift2" class="text-xs font-bold text-slate-600 dark:text-slate-300 cursor-pointer select-none" data-astro-cid-q3qq7mzj>Tambah shift kedua / setelah istirahat</label> </div> <!-- Shift 2 (Optional) --> <div id="shift2Container" class="grid grid-cols-1 sm:grid-cols-2 gap-4 hidden" data-astro-cid-q3qq7mzj> <div data-astro-cid-q3qq7mzj> <label class="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1.5 ml-1" data-astro-cid-q3qq7mzj>Mulai Shift 2</label> <input type="time" id="modalStartTime2" class="w-full h-11 px-4 rounded-xl border text-sm bg-slate-50 dark:bg-black/20 border-slate-200 dark:border-white/10 text-slate-900 dark:text-gray-100 focus:ring-2 focus:ring-accent focus:border-accent focus:outline-none transition-all font-semibold" data-astro-cid-q3qq7mzj> </div> <div data-astro-cid-q3qq7mzj> <label class="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1.5 ml-1" data-astro-cid-q3qq7mzj>Selesai Shift 2</label> <input type="time" id="modalEndTime2" class="w-full h-11 px-4 rounded-xl border text-sm bg-slate-50 dark:bg-black/20 border-slate-200 dark:border-white/10 text-slate-900 dark:text-gray-100 focus:ring-2 focus:ring-accent focus:border-accent focus:outline-none transition-all font-semibold" data-astro-cid-q3qq7mzj> </div> </div> <!-- Live Calculated Hours Indicator --> <div class="flex items-center justify-end px-1.5" data-astro-cid-q3qq7mzj> <span id="liveHoursIndicator" class="text-xs font-black uppercase tracking-wider text-blue-600 dark:text-blue-400 bg-blue-500/10 border border-blue-500/20 px-3 py-1 rounded-full" data-astro-cid-q3qq7mzj>
Total: 0 jam
</span> </div> </div> <!-- Non-Kerja reason fields --> <div id="leaveFields" data-astro-cid-q3qq7mzj> <label class="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1.5 ml-1" data-astro-cid-q3qq7mzj>Keterangan / Alasan</label> <textarea id="modalReason" rows="2" placeholder="Contoh: Acara keluarga / demam..." class="w-full p-4 rounded-xl border text-sm bg-slate-50 dark:bg-black/20 border-slate-200 dark:border-white/10 text-slate-900 dark:text-gray-100 focus:ring-2 focus:ring-accent focus:border-accent focus:outline-none transition-all font-semibold" data-astro-cid-q3qq7mzj></textarea> </div> <!-- Notes Admin --> <div data-astro-cid-q3qq7mzj> <label class="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1.5 ml-1" data-astro-cid-q3qq7mzj>Catatan Admin (Internal)</label> <input type="text" id="modalNotesAdmin" placeholder="Catatan opsional..." class="w-full h-11 px-4 rounded-xl border text-sm bg-slate-50 dark:bg-black/20 border-slate-200 dark:border-white/10 text-slate-900 dark:text-gray-100 focus:ring-2 focus:ring-accent focus:border-accent focus:outline-none transition-all font-semibold" data-astro-cid-q3qq7mzj> </div> <!-- Approval options for pending leave requests --> <div id="approvalSection" class="p-4 bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-900/50 rounded-2xl hidden space-y-2" data-astro-cid-q3qq7mzj> <p class="text-xs font-bold text-amber-800 dark:text-amber-200" data-astro-cid-q3qq7mzj>Pengajuan Karyawan (Pending)</p> <div class="flex gap-2" data-astro-cid-q3qq7mzj> <button type="button" id="btnApproveRequest" class="flex-1 h-9 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl text-[10px] font-black uppercase tracking-wider transition-all active:scale-95" data-astro-cid-q3qq7mzj>Setujui</button> <button type="button" id="btnRejectRequest" class="flex-1 h-9 bg-rose-600 hover:bg-rose-500 text-white rounded-xl text-[10px] font-black uppercase tracking-wider transition-all active:scale-95" data-astro-cid-q3qq7mzj>Tolak</button> </div> </div> <!-- Footer actions --> <div class="flex justify-between items-center pt-4" data-astro-cid-q3qq7mzj> <div data-astro-cid-q3qq7mzj> <button type="button" id="btnDeleteRecord" class="h-11 px-5 rounded-2xl bg-rose-50 dark:bg-rose-500/10 text-rose-600 hover:bg-rose-100 dark:hover:bg-rose-500/20 text-[10px] font-black uppercase tracking-widest transition-all active:scale-95 hidden" data-astro-cid-q3qq7mzj>
Hapus Jadwal
</button> </div> <div class="flex gap-3" data-astro-cid-q3qq7mzj> <button type="button" id="closeScheduleModalBtn" class="h-11 px-5 rounded-2xl bg-slate-100 dark:bg-white/5 border border-slate-200 dark:border-white/10 text-slate-700 dark:text-slate-300 text-[10px] font-black uppercase tracking-widest transition-all active:scale-95" data-astro-cid-q3qq7mzj>
Batal
</button> <button type="submit" id="btnSaveSchedule" class="h-11 px-6 rounded-2xl bg-blue-600 hover:bg-blue-500 text-white text-[10px] font-black uppercase tracking-widest transition-all shadow-xl shadow-blue-500/25 active:scale-95" data-astro-cid-q3qq7mzj>
Simpan
</button> </div> </div> </form> </div> </div> <div id="bulkActionBar" class="fixed bottom-6 left-1/2 -translate-x-1/2 z-40 w-[92%] sm:w-auto bg-slate-900/90 dark:bg-black/90 backdrop-blur-md border border-white/10 px-4 py-3 sm:px-6 sm:py-4 rounded-2xl flex flex-wrap sm:flex-nowrap items-center justify-between sm:justify-start gap-2 sm:gap-4 shadow-2xl transition-all duration-300 scale-90 opacity-0 pointer-events-none" data-astro-cid-q3qq7mzj> <span class="text-xs font-bold text-white whitespace-nowrap" data-astro-cid-q3qq7mzj><span id="selectedCellsCount" class="font-black text-blue-400" data-astro-cid-q3qq7mzj>0</span> sel terpilih</span> <div class="flex items-center gap-2 flex-wrap sm:flex-nowrap" data-astro-cid-q3qq7mzj> <button type="button" id="btnBulkEdit" class="h-9 px-3 sm:px-4 bg-blue-600 hover:bg-blue-500 text-white rounded-xl text-[10px] font-black uppercase tracking-wider transition-all active:scale-95 whitespace-nowrap" data-astro-cid-q3qq7mzj>Edit Bersama</button> <button type="button" id="btnBulkDelete" class="h-9 px-3 sm:px-4 bg-rose-600 hover:bg-rose-500 text-white rounded-xl text-[10px] font-black uppercase tracking-wider transition-all active:scale-95 whitespace-nowrap" data-astro-cid-q3qq7mzj>Hapus</button> <button type="button" id="btnCancelBulk" class="h-9 px-3 text-slate-400 hover:text-white rounded-xl text-[10px] font-black uppercase tracking-wider transition-all active:scale-95 whitespace-nowrap border border-white/10 sm:border-0" data-astro-cid-q3qq7mzj>Batal</button> </div> </div><script>
        // --- Mobile View Tab Switcher ---
        const tabKaryawan = document.getElementById("mobileTabKaryawan");
        const tabTanggal = document.getElementById("mobileTabTanggal");
        const contentKaryawan = document.getElementById("mobileContentKaryawan");
        const contentTanggal = document.getElementById("mobileContentTanggal");

        tabKaryawan?.addEventListener("click", () => {
            tabKaryawan.classList.add("bg-blue-600", "text-white", "shadow-md", "shadow-blue-500/20");
            tabKaryawan.classList.remove("bg-slate-100", "dark:bg-white/5", "text-slate-500", "dark:text-slate-400");
            tabTanggal?.classList.remove("bg-blue-600", "text-white", "shadow-md", "shadow-blue-500/20");
            tabTanggal?.classList.add("bg-slate-100", "dark:bg-white/5", "text-slate-500", "dark:text-slate-400");
            contentKaryawan?.classList.remove("hidden");
            contentTanggal?.classList.add("hidden");
        });

        tabTanggal?.addEventListener("click", () => {
            tabTanggal.classList.add("bg-blue-600", "text-white", "shadow-md", "shadow-blue-500/20");
            tabTanggal.classList.remove("bg-slate-100", "dark:bg-white/5", "text-slate-500", "dark:text-slate-400");
            tabKaryawan?.classList.remove("bg-blue-600", "text-white", "shadow-md", "shadow-blue-500/20");
            tabKaryawan?.classList.add("bg-slate-100", "dark:bg-white/5", "text-slate-500", "dark:text-slate-400");
            contentTanggal?.classList.remove("hidden");
            contentKaryawan?.classList.add("hidden");
        });

        // --- 1. Modal 1 Handlers: Ajukan Cuti (All Employees) ---
        const requestModal = document.getElementById("requestModal");
        const openRequestModalBtn = document.getElementById("openRequestModalBtn");
        const closeRequestModalBtn = document.getElementById("closeRequestModalBtn");

        openRequestModalBtn?.addEventListener("click", () => {
            requestModal?.classList.remove("hidden");
        });
        closeRequestModalBtn?.addEventListener("click", () => {
            requestModal?.classList.add("hidden");
        });

        const requestLeaveForm = document.getElementById("requestLeaveForm");
        requestLeaveForm?.addEventListener("submit", async (e) => {
            e.preventDefault();
            const startDate = document.getElementById("reqStartDate").value;
            const endDate = document.getElementById("reqEndDate").value;
            const type = document.getElementById("reqType").value;
            const reason = document.getElementById("reqReason").value;

            if (new Date(startDate) > new Date(endDate)) {
                alert("Tanggal mulai tidak boleh melebihi tanggal selesai!");
                return;
            }

            try {
                const res = await fetch("/api/absensi/request-leave", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ startDate, endDate, type, reason }),
                });
                const data = await res.json();
                if (data.success) {
                    alert("Pengajuan cuti/izin berhasil dikirim dan menunggu persetujuan admin!");
                    window.location.reload();
                } else {
                    alert(data.error || "Gagal mengirim pengajuan.");
                }
            } catch (err) {
                console.error(err);
                alert("Terjadi kesalahan sistem.");
            }
        });

        // --- 2. Modal 2 Handlers: Set Schedule (Admin Only) ---
        const scheduleModal = document.getElementById("scheduleModal");
        const modalRecordId = document.getElementById("modalRecordId");
        const modalUserId = document.getElementById("modalUserId");
        const modalEmployeeName = document.getElementById("modalEmployeeName");
        const modalStartDate = document.getElementById("modalStartDate");
        const modalEndDate = document.getElementById("modalEndDate");
        const modalType = document.getElementById("modalType");
        const modalReason = document.getElementById("modalReason");
        const modalNotesAdmin = document.getElementById("modalNotesAdmin");
        const kerjaFields = document.getElementById("kerjaFields");
        const leaveFields = document.getElementById("leaveFields");
        const btnDeleteRecord = document.getElementById("btnDeleteRecord");
        const approvalSection = document.getElementById("approvalSection");
        const modalTitle = document.getElementById("modalTitle");

        // Time inputs
        const modalStartTime1 = document.getElementById("modalStartTime1");
        const modalEndTime1 = document.getElementById("modalEndTime1");
        const enableShift2 = document.getElementById("enableShift2");
        const shift2Container = document.getElementById("shift2Container");
        const modalStartTime2 = document.getElementById("modalStartTime2");
        const modalEndTime2 = document.getElementById("modalEndTime2");
        const liveHoursIndicator = document.getElementById("liveHoursIndicator");
        const dayChecklistSection = document.getElementById("dayChecklistSection");

        // --- 3. Bulk Select State & UI (Admin Only) ---
        let isMultiSelectMode = false;
        let selectedCells = []; // array of cell elements

        const bulkActionBar = document.getElementById("bulkActionBar");
        const selectedCellsCount = document.getElementById("selectedCellsCount");
        const btnBulkEdit = document.getElementById("btnBulkEdit");
        const btnBulkDelete = document.getElementById("btnBulkDelete");
        const btnCancelBulk = document.getElementById("btnCancelBulk");

        const scheduleTable = document.getElementById("scheduleTable");

        function clearBulkSelection() {
            selectedCells.forEach(cell => {
                cell.classList.remove("ring-4", "ring-blue-500", "scale-[0.98]", "bg-blue-500/10", "z-10", "is-selected");
            });
            selectedCells = [];
            updateBulkBar();
        }

        function updateBulkBar() {
            if (selectedCellsCount) selectedCellsCount.innerText = selectedCells.length;
            if (selectedCells.length > 0) {
                isMultiSelectMode = true;
                bulkActionBar?.classList.remove("opacity-0", "pointer-events-none", "scale-90");
                bulkActionBar?.classList.add("opacity-100", "scale-100");
                scheduleTable?.classList.add("bulk-select-active");
            } else {
                isMultiSelectMode = false;
                bulkActionBar?.classList.add("opacity-0", "pointer-events-none", "scale-90");
                bulkActionBar?.classList.remove("opacity-100", "scale-100");
                scheduleTable?.classList.remove("bulk-select-active");
            }
        }

        btnCancelBulk?.addEventListener("click", () => {
            clearBulkSelection();
        });

        function getHoursDiff(start, end) {
            if (!start || !end) return 0;
            const [sH, sM] = start.split(":").map(Number);
            const [eH, eM] = end.split(":").map(Number);
            const diffMinutes = (eH * 60 + eM) - (sH * 60 + sM);
            return diffMinutes > 0 ? diffMinutes / 60 : 0;
        }

        function calculateLiveHours() {
            const start1 = modalStartTime1?.value || "";
            const end1 = modalEndTime1?.value || "";
            const hasShift2 = enableShift2?.checked || false;
            const start2 = modalStartTime2?.value || "";
            const end2 = modalEndTime2?.value || "";

            let total = getHoursDiff(start1, end1);
            if (hasShift2) {
                total += getHoursDiff(start2, end2);
            }

            if (liveHoursIndicator) {
                liveHoursIndicator.innerText = `Total: ${Math.round(total)} jam`;
            }
        }

        modalStartTime1?.addEventListener("input", calculateLiveHours);
        modalEndTime1?.addEventListener("input", calculateLiveHours);
        modalStartTime2?.addEventListener("input", calculateLiveHours);
        modalEndTime2?.addEventListener("input", calculateLiveHours);
        
        const addOneHour = (timeStr) => {
            if (!timeStr) return "";
            const [hours, minutes] = timeStr.split(":").map(Number);
            const newHours = (hours + 1) % 24;
            return `${String(newHours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
        };

        modalEndTime1?.addEventListener("change", () => {
            if (enableShift2?.checked && modalStartTime2 && !modalStartTime2.value && modalEndTime1?.value) {
                modalStartTime2.value = addOneHour(modalEndTime1.value);
                calculateLiveHours();
            }
        });

        enableShift2?.addEventListener("change", (e) => {
            if (shift2Container) {
                shift2Container.style.display = e.target.checked ? "grid" : "none";
            }
            if (e.target.checked) {
                modalStartTime2?.setAttribute("required", "true");
                modalEndTime2?.setAttribute("required", "true");
                if (modalStartTime2 && !modalStartTime2.value && modalEndTime1?.value) {
                    modalStartTime2.value = addOneHour(modalEndTime1.value);
                    if (modalEndTime2 && !modalEndTime2.value) {
                        modalEndTime2.value = addOneHour(modalStartTime2.value);
                    }
                }
            } else {
                modalStartTime2?.removeAttribute("required");
                modalEndTime2?.removeAttribute("required");
            }
            calculateLiveHours();
        });

        function toggleFields(type) {
            if (type === "Kerja") {
                if (kerjaFields) kerjaFields.style.display = "block";
                if (leaveFields) leaveFields.style.display = "none";
                modalStartTime1?.setAttribute("required", "true");
                modalEndTime1?.setAttribute("required", "true");
            } else {
                if (kerjaFields) kerjaFields.style.display = "none";
                if (leaveFields) leaveFields.style.display = "block";
                modalStartTime1?.removeAttribute("required");
                modalEndTime1?.removeAttribute("required");
                modalStartTime2?.removeAttribute("required");
                modalEndTime2?.removeAttribute("required");
            }
        }

        modalType?.addEventListener("change", (e) => {
            toggleFields(e.target.value);
        });

        // Add click listener to all cells
        const cells = document.querySelectorAll(".schedule-cell");
        cells.forEach(cell => {
            cell.addEventListener("click", (e) => {
                const isAdmin = cell.getAttribute("data-is-admin") === "true";
                if (!isAdmin) return; // Non-admin cannot edit

                const isCheckboxClick = e.target.closest(".select-checkbox-indicator");

                if (isMultiSelectMode || isCheckboxClick) {
                    // Toggle cell selection in Bulk mode
                    const idx = selectedCells.indexOf(cell);
                    if (idx > -1) {
                        selectedCells.splice(idx, 1);
                        cell.classList.remove("ring-4", "ring-blue-500", "scale-[0.98]", "bg-blue-500/10", "z-10", "is-selected");
                    } else {
                        selectedCells.push(cell);
                        cell.classList.add("ring-4", "ring-blue-500", "scale-[0.98]", "bg-blue-500/10", "z-10", "is-selected");
                    }
                    updateBulkBar();
                    return;
                }

                // Normal single-cell edit mode
                const userId = cell.getAttribute("data-user-id");
                const userName = cell.getAttribute("data-user-name");
                const date = cell.getAttribute("data-date");
                const recordId = cell.getAttribute("data-record-id");
                const type = cell.getAttribute("data-type") || "Kerja";
                const reason = cell.getAttribute("data-reason") || "";
                const notesAdmin = cell.getAttribute("data-notes-admin") || "";
                const status = cell.getAttribute("data-status") || "";

                if (modalRecordId) modalRecordId.value = recordId || "";
                if (modalUserId) modalUserId.value = userId || "";
                if (modalEmployeeName) modalEmployeeName.value = userName || "";
                if (modalStartDate) {
                    modalStartDate.value = recordId ? cell.getAttribute("data-start-date") : date;
                    modalStartDate.setAttribute("required", "true");
                }
                if (modalEndDate) {
                    modalEndDate.value = recordId ? cell.getAttribute("data-end-date") : date;
                    modalEndDate.setAttribute("required", "true");
                }
                if (modalType) modalType.value = type;
                if (modalNotesAdmin) modalNotesAdmin.value = notesAdmin;

                let startTime1 = "09:00";
                let endTime1 = "17:00";
                let startTime2 = "";
                let endTime2 = "";
                let hasShift2 = false;

                if (type === "Kerja") {
                    if (recordId && reason) {
                        const intervals = reason.split("\n");
                        if (intervals[0]) {
                            const parts = intervals[0].split(" - ");
                            startTime1 = parts[0] || "09:00";
                            endTime1 = parts[1] || "17:00";
                        }
                        if (intervals[1]) {
                            const parts = intervals[1].split(" - ");
                            startTime2 = parts[0] || "";
                            endTime2 = parts[1] || "";
                            hasShift2 = true;
                        }
                    }
                    if (modalReason) modalReason.value = "";
                } else {
                    if (modalReason) modalReason.value = reason;
                }

                if (modalStartTime1) modalStartTime1.value = startTime1;
                if (modalEndTime1) modalEndTime1.value = endTime1;
                if (enableShift2) enableShift2.checked = hasShift2;
                if (modalStartTime2) modalStartTime2.value = startTime2;
                if (modalEndTime2) modalEndTime2.value = endTime2;

                if (shift2Container) {
                    shift2Container.style.display = hasShift2 ? "grid" : "none";
                }
                
                if (hasShift2) {
                    modalStartTime2?.setAttribute("required", "true");
                    modalEndTime2?.setAttribute("required", "true");
                } else {
                    modalStartTime2?.removeAttribute("required");
                    modalEndTime2?.removeAttribute("required");
                }

                calculateLiveHours();
                toggleFields(type);

                // Make sure employee name & date range containers are visible
                const empNameGroup = document.getElementById("modalEmployeeName")?.closest("div");
                if (empNameGroup) empNameGroup.style.display = "block";
                const dateRangeGroup = document.getElementById("modalStartDate")?.closest(".grid");
                if (dateRangeGroup) dateRangeGroup.style.display = "grid";

                // Show/hide day checklist & Delete button
                if (recordId) {
                    btnDeleteRecord?.classList.remove("hidden");
                    if (dayChecklistSection) dayChecklistSection.style.display = "none";
                    if (modalTitle) modalTitle.innerText = "Edit Jadwal / Status";
                } else {
                    btnDeleteRecord?.classList.add("hidden");
                    if (dayChecklistSection) dayChecklistSection.style.display = "block";
                    if (modalTitle) modalTitle.innerText = "Set Jadwal Baru";
                }

                // Show/hide approval section (only for Pending requests)
                if (recordId && status === "Pending") {
                    approvalSection?.classList.remove("hidden");
                } else {
                    approvalSection?.classList.add("hidden");
                }

                scheduleModal?.classList.remove("hidden");
            });
        });

        // Close Schedule Modal
        const closeScheduleModalBtn = document.getElementById("closeScheduleModalBtn");
        closeScheduleModalBtn?.addEventListener("click", () => {
            scheduleModal?.classList.add("hidden");
            window.isBulkEdit = false;
        });

        // Bulk Edit Button Clicked
        btnBulkEdit?.addEventListener("click", () => {
            if (selectedCells.length === 0) return;
            
            // Set bulk edit flag
            window.isBulkEdit = true;
            
            if (modalRecordId) modalRecordId.value = "";
            if (modalUserId) modalUserId.value = "";
            if (modalTitle) modalTitle.innerText = `Edit Bersama (${selectedCells.length} Sel)`;
            
            // Hide single-edit specific containers
            const empNameGroup = document.getElementById("modalEmployeeName")?.closest("div");
            if (empNameGroup) empNameGroup.style.display = "none";
            const dateRangeGroup = document.getElementById("modalStartDate")?.closest(".grid");
            if (dateRangeGroup) dateRangeGroup.style.display = "none";
            if (dayChecklistSection) dayChecklistSection.style.display = "none";
            
            // Remove required attribute for bulk edit
            if (modalStartDate) {
                modalStartDate.value = "";
                modalStartDate.removeAttribute("required");
            }
            if (modalEndDate) {
                modalEndDate.value = "";
                modalEndDate.removeAttribute("required");
            }
            
            btnDeleteRecord?.classList.add("hidden");
            approvalSection?.classList.add("hidden");
            
            // Default Kerja field values
            if (modalType) modalType.value = "Kerja";
            if (modalStartTime1) modalStartTime1.value = "09:00";
            if (modalEndTime1) modalEndTime1.value = "17:00";
            if (enableShift2) enableShift2.checked = false;
            if (modalStartTime2) modalStartTime2.value = "";
            if (modalEndTime2) modalEndTime2.value = "";
            if (shift2Container) shift2Container.style.display = "none";
            if (modalReason) modalReason.value = "";
            if (modalNotesAdmin) modalNotesAdmin.value = "";

            toggleFields("Kerja");
            calculateLiveHours();
            scheduleModal?.classList.remove("hidden");
        });

        // Submit Schedule Form (Create / Update / Bulk)
        const scheduleForm = document.getElementById("scheduleForm");
        scheduleForm?.addEventListener("submit", async (e) => {
            e.preventDefault();
            const type = modalType?.value;
            const notesAdmin = modalNotesAdmin?.value || "";

            let payload = {
                type,
                notesAdmin
            };

            if (type === "Kerja") {
                payload.startTime1 = modalStartTime1?.value || "";
                payload.endTime1 = modalEndTime1?.value || "";
                if (enableShift2?.checked) {
                    payload.startTime2 = modalStartTime2?.value || "";
                    payload.endTime2 = modalEndTime2?.value || "";
                }
            } else {
                payload.reason = modalReason?.value || "";
            }

            if (window.isBulkEdit) {
                // Populate bulkItems from selectedCells array
                payload.bulkItems = selectedCells.map(cell => ({
                    userId: parseInt(cell.getAttribute("data-user-id")),
                    date: cell.getAttribute("data-date"),
                    recordId: cell.getAttribute("data-record-id") ? parseInt(cell.getAttribute("data-record-id")) : undefined
                }));
            } else {
                const id = modalRecordId?.value;
                const userId = modalUserId?.value;
                const startDate = modalStartDate?.value;
                const endDate = modalEndDate?.value;

                payload.id = id ? parseInt(id) : undefined;
                payload.userId = parseInt(userId);
                payload.startDate = startDate;
                payload.endDate = endDate;

                if (!id) {
                    const checkboxes = document.querySelectorAll('input[name="checkedWeekdays"]:checked');
                    const checkedDays = Array.from(checkboxes).map(cb => cb.value);
                    if (checkedDays.length === 0) {
                        alert("Pilih setidaknya satu hari kerja pada checklist!");
                        return;
                    }
                    payload.checkedDays = checkedDays;
                }

                if (new Date(startDate) > new Date(endDate)) {
                    alert("Tanggal mulai tidak boleh melebihi tanggal selesai!");
                    return;
                }
            }

            try {
                const res = await fetch("/api/absensi/create-manual", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                if (data.success) {
                    alert(window.isBulkEdit ? "Jadwal masal berhasil diperbarui!" : (payload.id ? "Jadwal berhasil diperbarui!" : "Jadwal baru berhasil disimpan!"));
                    window.location.reload();
                } else {
                    alert(data.error || "Gagal menyimpan jadwal.");
                }
            } catch (err) {
                console.error(err);
                alert("Terjadi kesalahan sistem.");
            }
        });

        // Delete Schedule Event
        btnDeleteRecord?.addEventListener("click", async () => {
            const id = modalRecordId?.value;
            if (!id) return;
            if (!confirm("Apakah Anda yakin ingin menghapus jadwal ini secara permanen?")) return;

            try {
                const res = await fetch("/api/absensi/delete-leave", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ id: parseInt(id) })
                });
                const data = await res.json();
                if (data.success) {
                    alert("Jadwal berhasil dihapus!");
                    window.location.reload();
                } else {
                    alert(data.error || "Gagal menghapus data.");
                }
            } catch (err) {
                console.error(err);
                alert("Terjadi kesalahan sistem.");
            }
        });

        // Bulk Delete Event
        btnBulkDelete?.addEventListener("click", async () => {
            if (selectedCells.length === 0) return;
            
            const recordIds = selectedCells
                .map(cell => cell.getAttribute("data-record-id"))
                .filter(id => id !== "")
                .map(Number);
                
            if (recordIds.length === 0) {
                alert("Tidak ada jadwal aktif pada sel yang dipilih untuk dihapus.");
                return;
            }
            
            if (!confirm(`Apakah Anda yakin ingin menghapus ${recordIds.length} jadwal terpilih secara permanen?`)) {
                return;
            }

            try {
                const res = await fetch("/api/absensi/delete-leave", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ ids: recordIds })
                });
                const data = await res.json();
                if (data.success) {
                    alert("Jadwal masal berhasil dihapus!");
                    window.location.reload();
                } else {
                    alert(data.error || "Gagal menghapus jadwal.");
                }
            } catch (err) {
                console.error(err);
                alert("Terjadi kesalahan sistem.");
            }
        });

        // Approve Request (Pending) from modal
        const btnApproveRequest = document.getElementById("btnApproveRequest");
        btnApproveRequest?.addEventListener("click", async () => {
            const id = modalRecordId?.value;
            if (!id) return;
            const notes = modalNotesAdmin?.value || "";

            try {
                const res = await fetch("/api/absensi/approve-leave", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ id: parseInt(id), status: "Approved", notesAdmin: notes })
                });
                const data = await res.json();
                if (data.success) {
                    alert("Pengajuan cuti/izin disetujui!");
                    window.location.reload();
                } else {
                    alert(data.error || "Gagal menyetujui pengajuan.");
                }
            } catch (err) {
                console.error(err);
                alert("Terjadi kesalahan sistem.");
            }
        });

        // Reject Request (Pending) from modal
        const btnRejectRequest = document.getElementById("btnRejectRequest");
        btnRejectRequest?.addEventListener("click", async () => {
            const id = modalRecordId?.value;
            if (!id) return;
            const notes = modalNotesAdmin?.value || "";
            if (!notes || !notes.trim()) {
                alert("Mohon masukkan alasan penolakan pada kolom Catatan Admin terlebih dahulu!");
                return;
            }

            try {
                const res = await fetch("/api/absensi/approve-leave", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ id: parseInt(id), status: "Rejected", notesAdmin: notes })
                });
                const data = await res.json();
                if (data.success) {
                    alert("Pengajuan cuti/izin ditolak!");
                    window.location.reload();
                } else {
                    alert(data.error || "Gagal menolak pengajuan.");
                }
            } catch (err) {
                console.error(err);
                alert("Terjadi kesalahan sistem.");
            }
        });

        // Auto Scroll to Today's Date
        const today = new Date();
        const currentDay = today.getDate();
        const currentMonth = (today.getMonth() + 1).toString().padStart(2, "0");
        const currentYear = today.getFullYear().toString();

        const urlParams = new URLSearchParams(window.location.search);
        const activeMonth = urlParams.get('month') || currentMonth;
        const activeYear = urlParams.get('year') || currentYear;

        if (activeMonth === currentMonth && activeYear === currentYear) {
            const targetHeader = document.querySelector(`th[data-day="${currentDay}"]`);
            if (targetHeader) {
                const scrollContainer = targetHeader.closest('.overflow-x-auto');
                if (scrollContainer) {
                    // Give a slight delay to ensure render is completed
                    setTimeout(() => {
                        const stickyCol = scrollContainer.querySelector('.sticky');
                        const stickyWidth = stickyCol ? stickyCol.offsetWidth : 0;
                        scrollContainer.scrollTo({
                            left: targetHeader.offsetLeft - stickyWidth - 10,
                            behavior: 'smooth'
                        });
                    }, 350);
                }
            }
        }
    </script>  </main> </div> <!-- Sticky Bottom Navigation Bar for Mobile --> <div class="lg:hidden fixed bottom-0 left-0 right-0 w-full bg-white/85 dark:bg-slate-900/85 backdrop-blur-xl border-t border-theme-border/40 z-30 bottom-nav-safe-area shadow-[0_-4px_12px_rgba(0,0,0,0.05)] print:hidden"> <div class="flex justify-around items-center h-[52px] px-2"> <!-- Beranda --> <a href="/dashboard" class="flex flex-col items-center justify-center flex-1 pt-1.5 pb-1 transition-all duration-200 gap-0.5 text-theme-text-secondary hover:text-theme-text font-medium"> <svg class="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"> <path stroke-linecap="round" stroke-linejoin="round" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"></path> </svg> <span class="text-[10px]">Beranda</span> </a> <!-- Kasir --> <a href="/kasir" class="flex flex-col items-center justify-center flex-1 pt-1.5 pb-1 transition-all duration-200 gap-0.5 text-theme-text-secondary hover:text-theme-text font-medium"> <svg class="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"> <path stroke-linecap="round" stroke-linejoin="round" d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 100 4 2 2 0 000-4z"></path> </svg> <span class="text-[10px]">Kasir</span> </a> <!-- Servis --> <a href="/servis" class="flex flex-col items-center justify-center flex-1 pt-1.5 pb-1 transition-all duration-200 gap-0.5 text-theme-text-secondary hover:text-theme-text font-medium"> <svg class="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"> <path stroke-linecap="round" stroke-linejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.066 2.573c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1